class SxTpSlTests(unittest.TestCase):
    """State X window ban and daily take-profit / stop-loss."""

    def setUp(self) -> None:
        self.dir = tempfile.TemporaryDirectory()
        self.addCleanup(self.dir.cleanup)
        self.store = Store(Path(self.dir.name) / "sxtp.sqlite3")
        self.controls = TradeControls(self.store)
        self.sx = self.controls.state_x
        self.t0 = candle_id_from_ms(now_ms()) - 3_600_000

    # ---- State X -----------------------------------------------------
    def test_two_consecutive_losses_open_a_window(self) -> None:
        self.sx.apply_toggle(True, self.t0)
        self.assertFalse(self.sx.execution_block(self.t0)[0])
        self.sx.note_settled_result(False, self.t0)
        self.assertFalse(self.sx.execution_block(self.t0 + 1)[0])
        r = self.sx.note_settled_result(False, self.t0 + 2)
        self.assertTrue(r["opened"])
        blocked, fields = self.sx.execution_block(self.t0 + 3)
        self.assertTrue(blocked)
        self.assertEqual(fields["state_x"], "SX")
        self.assertTrue(fields["state_x_active"])
        snap = self.sx.snapshot(self.t0 + 3)
        self.assertTrue(snap["active"])
        self.assertEqual(snap["status"], "ACTIVE · BLOCKING")
        self.assertEqual(snap["trigger_count"], 1)
        self.assertGreater(snap["remaining_ms"], 0)

    def test_a_win_resets_the_streak(self) -> None:
        self.sx.apply_toggle(True, self.t0)
        self.sx.note_settled_result(False, self.t0)
        self.sx.note_settled_result(True, self.t0 + 1)
        self.sx.note_settled_result(False, self.t0 + 2)
        self.assertFalse(self.sx.execution_block(self.t0 + 3)[0])

    def test_window_expires_after_ban_duration(self) -> None:
        self.sx.apply_toggle(True, self.t0)
        self.sx.note_settled_result(False, self.t0)
        self.sx.note_settled_result(False, self.t0 + 1)
        end = self.t0 + 1 + STATE_X_BAN_MS
        self.assertTrue(self.sx.execution_block(end - 1)[0])
        self.assertFalse(self.sx.execution_block(end)[0])
        self.assertFalse(self.sx.snapshot(end)["active"])

    def test_switch_off_tracks_but_never_blocks(self) -> None:
        self.sx.apply_toggle(False, self.t0)
        self.sx.note_settled_result(False, self.t0)
        r = self.sx.note_settled_result(False, self.t0 + 1)
        self.assertTrue(r["opened"])
        blocked, fields = self.sx.execution_block(self.t0 + 2)
        self.assertFalse(blocked)
        self.assertEqual(fields["state_x"], "")
        snap = self.sx.snapshot(self.t0 + 2)
        self.assertTrue(snap["active"])
        self.assertEqual(snap["status"], "ACTIVE · SHADOW (switch OFF)")

    def test_losses_during_an_open_window_do_not_reopen_it(self) -> None:
        self.sx.apply_toggle(True, self.t0)
        self.sx.note_settled_result(False, self.t0)
        self.sx.note_settled_result(False, self.t0 + 1)
        first_end = self.sx.snapshot(self.t0 + 2)["end_time_ms"]
        for k in range(4):
            self.sx.note_settled_result(False, self.t0 + 10 + k)
        self.assertEqual(self.sx.snapshot(self.t0 + 20)["end_time_ms"], first_end)
        self.assertEqual(self.sx.snapshot(self.t0 + 20)["trigger_count"], 1)

    def test_settlement_path_feeds_state_x(self) -> None:
        source = Path(__file__).read_text(encoding="utf-8")
        tree = ast.parse(source)
        hits = 0
        for node in tree.body:
            if isinstance(node, ast.ClassDef) and node.name in ("Engine", "LiveExecutor"):
                for m in node.body:
                    if isinstance(m, ast.FunctionDef):
                        seg = ast.get_source_segment(source, m) or ""
                        if "record_result(" in seg and "note_settled_result(" in seg:
                            hits += 1
        self.assertGreaterEqual(hits, 3)

    # ---- daily TP / SL -----------------------------------------------
    def _real_trade(self, cid: int, pnl: float) -> None:
        self.store.record_trade({
            "candle_id": cid, "kind": "EF", "direction": "UP", "ts_ms": cid + 1000,
            "seconds_into_candle": 1.0, "quoted_price": 0.30, "fill_price": 0.30,
            "slippage": 0.0, "delay_ms": 1, "attempts": 1, "filled": True,
            "stake": 10.0, "shares": 33.0, "execution_mode": "LIVE",
            "order_status": "FILLED"})
        self.store.update_trade_execution(
            cid, "EF", financial_result="WIN" if pnl > 0 else "LOSS",
            financial_pnl=pnl, financial_is_shadow=False, filled=True,
            order_status="FILLED")

    def _enable_all(self) -> None:
        self.store.write_control(SYSTEM_CONTROL_KIND, manual_enabled=True)
        for k in TRADE_KINDS:
            self.store.write_control(k, manual_enabled=True)

    def test_limits_disabled_by_default(self) -> None:
        self.assertEqual(DAILY_TAKE_PROFIT_USD, 0.0)
        self.assertEqual(DAILY_STOP_LOSS_USD, 0.0)
        self._enable_all()
        for cid in range(5):
            self._real_trade(self.t0 + cid * 300_000, -50.0)
        self.assertEqual(self.controls.daily_halt(self.t0 + 2_000_000)[0], "")

    def test_stop_loss_halts_and_take_profit_halts(self) -> None:
        self._enable_all()
        day = (self.t0 // 86_400_000) * 86_400_000 + 3_600_000
        old = None
        try:
            self.controls.set_daily_limits(0, 100)
            self._real_trade(day, -60.0)
            self.controls._daily_cache = None
            self.assertEqual(self.controls.daily_halt(day + 1)[0], "")
            self._real_trade(day + 300_000, -60.0)
            self.controls._daily_cache = None
            reason, detail = self.controls.daily_halt(day + 600_000)
            self.assertIn("STOP-LOSS", reason)
            self.assertAlmostEqual(detail["pnl"], -120.0)
            self.controls.set_daily_limits(100, 0)
            self._real_trade(day + 600_000, 250.0)
            self.controls._daily_cache = None
            reason, _ = self.controls.daily_halt(day + 900_000)
            self.assertIn("TAKE-PROFIT", reason)
            # next UTC day trades again
            self.controls._daily_cache = None
            self.assertEqual(self.controls.daily_halt(day + 86_400_000)[0], "")
        finally:
            self.controls.set_daily_limits(0, 0)

    def test_limits_persist_and_drive_the_halt(self) -> None:
        self._enable_all()
        r = self.controls.set_daily_limits(250, 120)
        self.assertTrue(r["ok"])
        self.assertEqual(self.controls.daily_limits(), {"take_profit": 250.0, "stop_loss": 120.0})
        # survives a fresh TradeControls over the same database
        again = TradeControls(self.store)
        self.assertEqual(again.daily_limits()["stop_loss"], 120.0)
        day = (self.t0 // 86_400_000) * 86_400_000 + 3_600_000
        self._real_trade(day, -70.0); self._real_trade(day + 300_000, -70.0)
        again._daily_cache = None
        reason, detail = again.daily_halt(day + 600_000)
        self.assertIn("STOP-LOSS", reason)
        ok, why = again.may_execute("EF", day + 600_000)
        self.assertFalse(ok); self.assertIn("STOP-LOSS", why)
        snap = again.snapshot(day + 600_000)["daily_limits"]
        self.assertTrue(snap["halted"]); self.assertEqual(snap["stop_loss"], 120.0)
        self.assertFalse(self.controls.set_daily_limits(-1, 0)["ok"])

    def test_trading_day_rolls_at_london_noon_not_utc_midnight(self) -> None:
        # 09:00 London -> the day started at NOON YESTERDAY.
        morning = int(london_dt(now_ms()).replace(
            hour=9, minute=0, second=0, microsecond=0).timestamp() * 1000)
        start, end = trading_day_window(morning)
        self.assertEqual(london_dt(start).hour, TRADING_DAY_RESET_HOUR)
        self.assertEqual(london_dt(end).hour, TRADING_DAY_RESET_HOUR)
        self.assertLess(start, morning)
        self.assertGreater(end, morning)
        self.assertLess(london_dt(start).date(), london_dt(morning).date())
        # 15:00 the same day -> the day started at NOON TODAY.
        afternoon = morning + 6 * 3_600_000
        start2, end2 = trading_day_window(afternoon)
        self.assertEqual(london_dt(start2).date(), london_dt(afternoon).date())
        self.assertEqual(end2 - start2, end - start)
        self.assertEqual(start2, end)      # windows are contiguous
        # Days are whole days apart even across a DST change.
        for days in (1, 60, 120, 200):
            a, b = trading_day_window(morning + days * 86_400_000)
            self.assertEqual(london_dt(a).hour, TRADING_DAY_RESET_HOUR)
            self.assertEqual(london_dt(b).hour, TRADING_DAY_RESET_HOUR)

    def test_limit_counter_resets_at_noon_and_trading_resumes(self) -> None:
        self._enable_all()
        self.controls.set_daily_limits(0, 100)
        start, end = trading_day_window(now_ms())
        mid = start + 3_600_000
        self._real_trade(mid, -60.0); self._real_trade(mid + 300_000, -60.0)
        self.controls._daily_cache = None
        self.assertIn("STOP-LOSS", self.controls.daily_halt(mid + 600_000)[0])
        # Same losses, next trading day: counter is zero again, trading resumes.
        self.controls._daily_cache = None
        self.assertEqual(self.controls.daily_halt(end + 1_000)[0], "")
        self.assertEqual(self.controls.daily_halt(end + 1_000)[1]["pnl"], 0.0)
        self.controls.set_daily_limits(0, 0)

    def test_controls_page_exposes_limits_and_window_sx(self) -> None:
        self.assertIn('id="take_profit"', CONTROLS_HTML)
        self.assertIn('id="stop_loss"', CONTROLS_HTML)
        self.assertIn('id="saveLimits"', CONTROLS_HTML)
        self.assertIn("/api/controls/daily-limits", CONTROLS_HTML)
        self.assertIn("2 consecutive settled losses", CONTROLS_HTML)
        self.assertIn("limitsDirty", CONTROLS_HTML)       # refresh must not wipe typing
        self.assertIn('class="formGrid"', CONTROLS_HTML)  # two-column, not the page grid
        self.assertIn("noon to noon London time", CONTROLS_HTML)
        self.assertNotIn("until 00:00 UTC", CONTROLS_HTML)
        self.assertNotIn("per-trade only", CONTROLS_HTML)

    def test_shadow_pnl_never_counts_toward_limits(self) -> None:
        self._enable_all()
        day = (self.t0 // 86_400_000) * 86_400_000 + 3_600_000
        try:
            self.controls.set_daily_limits(0, 10)
            self.store.record_trade({
                "candle_id": day, "kind": "EF", "direction": "UP", "ts_ms": day + 1000,
                "seconds_into_candle": 1.0, "quoted_price": 0.30, "fill_price": None,
                "slippage": None, "delay_ms": 0, "attempts": 0, "filled": False,
                "stake": 10.0, "shares": 33.0, "execution_mode": "SHADOW",
                "order_status": "SHADOW"})
            self.store.update_trade_execution(
                day, "EF", financial_result="LOSS", financial_pnl=-500.0,
                financial_is_shadow=True)
            self.controls._daily_cache = None
            self.assertEqual(self.controls.daily_halt(day + 1)[0], "")
        finally:
            self.controls.set_daily_limits(0, 0)


class V911Tests(unittest.TestCase):
    def setUp(self) -> None:
        self.tmp = tempfile.TemporaryDirectory()
        self.store = Store(Path(self.tmp.name) / "v911.sqlite3")

    def tearDown(self) -> None:
        self.store.close()
        self.tmp.cleanup()

    def test_r660_recovery_is_not_subtracted_twice(self) -> None:
        row = ef_adaptive_settlement(20.0, 30.0, 100.0, 1.0, 0.5, 100.0)
        self.assertEqual(row["residual_distance"], 20.0)
        runway = ef_runway_v2(20.0, 30.0, 100.0, 1.0, 1.0, 1.0,
                              0.5, 0.5, 0.5, 0.5, 0.2, 0.5, 0.2, 100.0)
        self.assertEqual(runway["residual_distance"], 20.0)
        without_recovery = ef_adaptive_settlement(
            20.0, 0.0, 100.0, 1.0, 0.5, 100.0
        )
        self.assertEqual(
            row["settlement_probability"],
            without_recovery["settlement_probability"],
        )

    def test_ef_flow_flips_use_fixed_time_buckets(self) -> None:
        rows = [(1000, 1.0, 1.0, 10.0), (1500, 1.0, 1.0, -10.0),
                (2000, 1.0, 1.0, 10.0), (2500, 1.0, 1.0, 10.0)]
        self.assertEqual(Engine._ef_flow_flips_5s(rows, 2500), 2)

    def test_ef_flow_flips_are_invariant_to_callback_splitting(self) -> None:
        base = [(1000, 1.0, 1.0, 100.0), (1500, 1.0, 1.0, -100.0),
                (2000, 1.0, 1.0, 100.0)]
        split = [(1000, 1.0, 1.0, 25.0), (1100, 1.0, 1.0, 25.0),
                 (1200, 1.0, 1.0, 25.0), (1300, 1.0, 1.0, 25.0),
                 (1500, 1.0, 1.0, -50.0), (1600, 1.0, 1.0, -50.0),
                 (2000, 1.0, 1.0, 50.0), (2100, 1.0, 1.0, 50.0)]
        self.assertEqual(Engine._ef_flow_flips_5s(base, 2200), 2)
        self.assertEqual(Engine._ef_flow_flips_5s(split, 2200), 2)

    def test_r660_flow_persistence_is_callback_split_invariant(self) -> None:
        base = [(100, 1.0, 1.0, -100.0), (600, 1.0, 1.0, -80.0),
                (1100, 1.0, 1.0, 90.0), (1600, 1.0, 1.0, 120.0),
                (2100, 1.0, 1.0, 100.0)]
        split = []
        for stamp, price, qty, signed in base:
            split.extend((stamp+i*40, price, qty/4.0, signed/4.0) for i in range(4))
        first = ef_flow_transition_profile(base, 3000, 1.0)
        second = ef_flow_transition_profile(split, 3000, 1.0)
        for key in ("persistence", "transition", "support_fraction"):
            self.assertAlmostEqual(first[key], second[key], places=12)

    def test_r660_partial_bucket_impulse_is_not_persistence(self) -> None:
        history = [(100, 1.0, 1.0, -100.0), (600, 1.0, 1.0, -100.0),
                   (1100, 1.0, 1.0, -100.0), (1600, 1.0, 1.0, -100.0)]
        before = ef_flow_transition_profile(history, 2700, 1.0)
        with_impulse = ef_flow_transition_profile(
            history + [(2600, 1.0, 1.0, 10_000.0)], 2700, 1.0
        )
        self.assertEqual(before, with_impulse)

    def test_r660_depth_math_ignores_top5_tail_churn(self) -> None:
        old = {"bids": [(100,1),(99,1),(98,1),(97,1),(96,1)],
               "asks": [(101,1),(102,1),(103,1),(104,1),(105,1)]}
        tail = {"bids": [(100,1),(99,1),(98,1),(97,1),(95,7)],
                "asks": [(101,1),(102,1),(103,1),(104,1),(106,9)]}
        change = ef_depth_change(old, tail)
        self.assertEqual(change["bid_change"], 0.0)
        self.assertEqual(change["ask_change"], 0.0)
        self.assertEqual(ef_depth_event_ofi(old, tail), 0.0)
        improved = {"bids": [(101,2),(100,1),(99,1),(98,1),(97,1)],
                    "asks": list(old["asks"])}
        self.assertGreater(ef_depth_event_ofi(old, improved), 0.0)

    def test_r660_classifier_separates_real_from_impulse_fake(self) -> None:
        strong = ef_reversal_classifier(
            control=.80, exhaustion=.65, persistence=.75, flow_transition=.80,
            settlement=.72, new_effectiveness=.80, old_effectiveness=.15,
            rejection=.75, path_quality=.75, chop=.15, fast_support=.85,
            opposite_book=.60, old_side_book_replenishment=.05,
        )
        impulse = ef_reversal_classifier(
            control=.60, exhaustion=.25, persistence=.10, flow_transition=.30,
            settlement=.60, new_effectiveness=.60, old_effectiveness=.50,
            rejection=.25, path_quality=.35, chop=.65, fast_support=.90,
            opposite_book=-.10, old_side_book_replenishment=.50,
        )
        self.assertEqual(strong["reversal_class"], "REAL_REVERSAL")
        self.assertEqual(impulse["reversal_class"], "FAKE_REVERSAL")
        self.assertGreater(strong["real_reversal_score"], impulse["real_reversal_score"])

    def test_r660_ef_deduplicates_replayed_aggtrades_only(self) -> None:
        engine = Engine(self.store)
