    def test_r661_processor_start_is_singleton_under_race(self) -> None:
        engine = Engine(self.store)
        entered = threading.Event()
        release = threading.Event()

        def held_loop() -> None:
            entered.set()
            release.wait(1.0)

        engine._market_processor_loop = held_loop  # type: ignore[method-assign]
        starters = [threading.Thread(target=engine.start_processor) for _ in range(12)]
        for starter in starters:
            starter.start()
        for starter in starters:
            starter.join(1.0)
        self.assertTrue(entered.wait(1.0))
        live = [thread for thread in threading.enumerate()
                if thread.name == "btc-engine" and thread.is_alive()]
        self.assertEqual(len(live), 1)
        release.set()
        live[0].join(1.0)

    def test_r661_sliding_ef_windows_match_reference_across_expiry_and_capacity(self) -> None:
        engine = Engine(self.store)
        # A small source cap exercises eviction even inside the 30s window.
        engine.ef_trade_ticks = deque(maxlen=97)
        rng = random.Random(661)
        stamp = 100_000
        price = 100_000.0
        for index in range(1500):
            stamp += 31_001 if index % 313 == 312 else rng.choice((0, 2, 10, 25, 100))
            price += rng.choice((-.25, -.125, 0.0, .125, .25))
            qty = 0.0 if index % 23 == 0 else rng.uniform(.001, .1)
            engine._on_trade({"a": index+1, "T": stamp, "p": str(price),
                              "q": str(qty), "m": bool(index % 3)}, stamp, stamp)
            if index % 19:
                continue
            windows = engine._ef_cached_windows(stamp)
            for width, window in windows.items():
                expected = ef_trade_window(engine.ef_trade_ticks, stamp, width)
                for key, value in expected.items():
                    self.assertTrue(math.isclose(window.flow()[key], value,
                                                 rel_tol=1e-10, abs_tol=1e-7),
                                    (index, width, key, window.flow()[key], value))
                if window.track_path:
                    self.assertEqual(window.path(), ef_path_stats(engine.ef_trade_ticks, stamp, width))
        # A quiet market ages the cache even without a new trade callback.
        windows = engine._ef_cached_windows(stamp+31_001)
        self.assertTrue(all(not window.rows for window in windows.values()))

    def test_r661_sliding_ef_cache_rebuild_is_causal_after_clock_rewind(self) -> None:
        engine = Engine(self.store)
        engine.ef_trade_ticks.extend([
            (10_000, 100.0, 1.0, 100.0),
            (11_000, 101.0, 1.0, -101.0),
            (12_000, 102.0, 1.0, 102.0),
        ])
        engine._ef_cached_windows(12_000)
        windows = engine._ef_cached_windows(11_000)
        self.assertEqual(windows[5_000].flow(), ef_trade_window(engine.ef_trade_ticks, 11_000, 5_000))
        self.assertEqual(windows[5_000].path(), ef_path_stats(engine.ef_trade_ticks, 11_000, 5_000))
        windows = engine._ef_cached_windows(12_000)
        self.assertEqual(windows[5_000].flow(), ef_trade_window(engine.ef_trade_ticks, 12_000, 5_000))

