    def test_r661_second_process_lock_is_refused_and_recoverable(self) -> None:
        path = Path(self.tmp.name) / "one-owner.sqlite3"
        first = DatabaseRunLock(path)
        try:
            with self.assertRaisesRegex(RuntimeError, "already in use"):
                DatabaseRunLock(path)
        finally:
            first.release()
        second = DatabaseRunLock(path)
        second.release()

    def test_r661_ef_performance_audit_separates_direction_from_real_pnl(self) -> None:
        with self.store.lock:
            for index, (direction, actual, correct, pnl, result) in enumerate([
                ("UP", "UP", 1, 5.0, "WIN"),
                ("DOWN", "UP", 0, -10.0, "LOSS"),
            ], start=1):
                cid = index * CANDLE_MS
                self.store.db.execute(
                    "INSERT INTO candles(candle_id,open,high,low,close,volume,closed_ts_ms,actual) "
                    "VALUES(?,?,?,?,?,?,?,?)",
                    (cid, 100.0, 101.0, 99.0, 100.5, 1.0,
                     cid + CANDLE_MS - 1, actual),
                )
                self.store.db.execute(
                    "INSERT INTO ef_predictions(candle_id,direction,ts_ms,price," 
                    "probability_up,reason,actual,correct,features) "
                    "VALUES(?,?,?,?,?,?,?,?,?)",
                    (cid, direction, cid + 120_000, 100.0, 0.5,
                     "test", actual, correct, "{}"),
                )
                self.store.db.execute(
                    "INSERT INTO trades(candle_id,kind,direction,ts_ms,filled," 
                    "fill_price,stake,financial_result,financial_pnl," 
                    "financial_is_shadow,forbidden,state_x,order_status) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (cid, "EF", direction, cid + 120_000, 1, 0.5, 10.0,
                     result, pnl, 0, 0, "", "FILLED"),
                )
            self.store.db.commit()
        report = self.store.ef_performance_audit()
        self.assertEqual(report["fires_settled"], 2)
        self.assertEqual(report["directional_accuracy"], 0.5)
        self.assertEqual(report["fires_per_100_settled_candles"], 100.0)
        self.assertEqual(report["real_accuracy"], 0.5)
        self.assertEqual(report["real_pnl_usd"], -5.0)
        self.assertEqual(report["max_drawdown_usd"], 10.0)
        self.assertEqual(report["max_losing_streak"], 1)

    def test_r661_audit_excludes_unusable_economics_and_separates_shadow(self) -> None:
        cases = [
            (1, 0, "FILLED", "WIN", 5.0),
            (0, 1, "SHADOW", "LOSS", -3.0),
            (1, 0, "PARTIALLYFILLED", "WIN", 8.0),
            (0, 0, "ORDERNOTACCEPTED", "LOSS", -10.0),
            (1, 0, "FILLED", "WIN", None),
            (1, 0, "FILLED", "WIN", float("inf")),
            (1, 0, "FILLED", "FLAT", 0.0),
            # PnL sign remains authoritative if a stored label is stale.
            (1, 0, "FILLED", "WIN", -2.0),
        ]
        with self.store.lock:
            for index, (filled, shadow, status, result, pnl) in enumerate(cases, 1):
                self.store.db.execute(
                    "INSERT INTO trades(candle_id,kind,direction,ts_ms,filled,"
                    "financial_is_shadow,order_status,financial_result,financial_pnl,"
                    "stake,forbidden,state_x) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                    (index*CANDLE_MS, "EF", "UP", index*CANDLE_MS+1000,
                     filled, shadow, status, result, pnl, 10.0, 0, ""),
                )
            self.store.db.commit()
        report = self.store.ef_performance_audit()
        self.assertEqual(report["real_settled_trades"], 3)
        self.assertEqual(report["real_pnl_usd"], 3.0)
        self.assertEqual(report["real_accuracy"], 0.5)
        self.assertEqual(report["real_flat"], 1)
        self.assertEqual(report["shadow_settled_trades"], 1)
        self.assertEqual(report["shadow_pnl_usd"], -3.0)
        self.assertEqual(report["shadow_accuracy"], 0.0)
        self.assertIsNone(report["directional_accuracy"])

