        snap = prep.snapshot("UP", base + (EF_VOLATILITY_MIN_SAMPLES + 5) * 1000)
        self.assertGreater(snap["sigma_per_root_second"], 0.0)
        self.assertGreater(prep.health_snapshot()["sigma_per_root_second"], 0.0)

