class B27PerpEndpointTests(unittest.TestCase):
    """Build 27: /market trade lane + /public depth lane, independent."""
    @staticmethod
    def _agg(agg_id: int, ts: int, price: float, qty: str = "0.001", maker: bool = False) -> Dict[str, Any]:
        return {"e": "aggTrade", "E": ts, "s": "BTCUSDT", "a": agg_id, "p": f"{price:.2f}",
                "q": qty, "f": 1, "l": 1, "T": ts, "m": maker}

    @staticmethod
    def _depth(update_id: int, ts: int, mid: float = 79419.0) -> Dict[str, Any]:
        bids = [[f"{mid - 0.1 * (i + 1):.1f}", f"{1.0 + 0.01 * i:.3f}"] for i in range(20)]
        asks = [[f"{mid + 0.1 * (i + 1):.1f}", f"{1.0 + 0.01 * i:.3f}"] for i in range(20)]
        return {"e": "depthUpdate", "E": ts, "T": ts, "s": "BTCUSDT", "U": update_id * 10,
                "u": update_id * 10 + 9, "pu": update_id * 10 - 1, "b": bids, "a": asks}

    def test_A_trade_lane_uses_market_endpoint(self) -> None:
        self.assertEqual(EF_PERP_TRADE_WS_URL, "wss://fstream.binance.com/market/ws/btcusdt@aggTrade")
        lane = PerpLaneThread("trade", EFPerpPrep(), threading.Event())
        self.assertEqual(lane.url, EF_PERP_TRADE_WS_URL); self.assertEqual(lane.expected, "aggTrade")
        lanes = PerpFeedLanes(EFPerpPrep(), threading.Event())
        self.assertEqual(lanes.threads["trade"].url, EF_PERP_TRADE_WS_URL)

    def test_B_depth_lane_uses_public_endpoint(self) -> None:
        self.assertEqual(EF_PERP_DEPTH_WS_URL, "wss://fstream.binance.com/public/ws/btcusdt@depth20@100ms")
        lane = PerpLaneThread("depth", EFPerpPrep(), threading.Event())
        self.assertEqual(lane.url, EF_PERP_DEPTH_WS_URL); self.assertEqual(lane.expected, "depth")
        lanes = PerpFeedLanes(EFPerpPrep(), threading.Event())
        self.assertEqual(lanes.threads["depth"].url, EF_PERP_DEPTH_WS_URL)

    def test_C_market_aggtrade_payload_is_accepted(self) -> None:
        prep = EFPerpPrep(); ts = 1_800_000_000_000
        payload = {"e": "aggTrade", "E": ts, "a": 3440970535, "p": "79419.30", "q": "0.001", "T": ts, "m": False}
        kind, accepted = prep.route_message(payload, ts, "trade")
        self.assertEqual(kind, "aggTrade"); self.assertTrue(accepted)
        h = prep.health_snapshot(ts + 3)
        self.assertEqual(h["trade_accepts"], 1); self.assertEqual(h["trade_frames"], 1)
        self.assertEqual(h["trade_age_ms"], 3); self.assertEqual(h["last_stream_name"], "")

    def test_D_public_depth_payload_is_accepted(self) -> None:
        prep = EFPerpPrep(); ts = 1_800_000_000_000
        kind, accepted = prep.route_message(self._depth(1, ts), ts, "depth")
        self.assertEqual(kind, "depth"); self.assertTrue(accepted)
        h = prep.health_snapshot(ts + 2)
        self.assertEqual(h["depth_accepts"], 1); self.assertEqual(h["depth_frames"], 1)
        self.assertEqual(h["depth_age_ms"], 2); self.assertIsNone(h["trade_age_ms"])

    def test_E_lane_failures_are_independent(self) -> None:
        prep = EFPerpPrep(); stop = threading.Event()
        lanes = PerpFeedLanes(prep, stop)
        with mock.patch.object(PerpLaneThread, "start"), mock.patch.object(PerpLaneThread, "run"):
            lanes.start()
        trade, depth = lanes.threads["trade"], lanes.threads["depth"]
        # Trade lane dies; depth lane alive: only trade is recreated.
        with mock.patch.object(trade, "is_alive", return_value=False), \
             mock.patch.object(depth, "is_alive", return_value=True), \
             mock.patch.object(PerpLaneThread, "start"):
            self.assertEqual(lanes.ensure_alive(), ["trade"])
        self.assertIs(lanes.threads["depth"], depth); self.assertIsNot(lanes.threads["trade"], trade)
        # Depth lane dies; trade lane alive: only depth is recreated.
        trade2 = lanes.threads["trade"]
        with mock.patch.object(trade2, "is_alive", return_value=True), \
             mock.patch.object(depth, "is_alive", return_value=False), \
             mock.patch.object(PerpLaneThread, "start"):
            self.assertEqual(lanes.ensure_alive(), ["depth"])
        self.assertIs(lanes.threads["trade"], trade2); self.assertIsNot(lanes.threads["depth"], depth)
        # Status reporting keeps the two apart.
        prep.set_lane_status("trade", "live"); prep.set_lane_status("depth", "error", "boom")
        h = prep.health_snapshot()
        self.assertEqual(h["trade_status"], "live"); self.assertEqual(h["depth_status"], "error")
        self.assertEqual(h["depth_error"], "boom"); self.assertEqual(h["status"], "trade live, depth error")
        prep.set_lane_status("depth", "live")
        self.assertEqual(prep.health_snapshot()["status"], "live")
        prep.note_lane_reconnect("depth")
        self.assertEqual(prep.health_snapshot()["depth_reconnects"], 1)
        self.assertEqual(prep.health_snapshot()["trade_reconnects"], 0)

    def _warm(self, prep: EFPerpPrep, now: int, trades: bool, depth: bool, depth_age: int = 100) -> None:
        prep.set_lane_status("trade", "live"); prep.set_lane_status("depth", "live")
        agg = 1
        if trades:
            for i in range(40):
                ts = now - 4_000 + i * 100
                prep.route_message(self._agg(agg, ts, 79419 + 0.1 * (i % 4)), ts, "trade"); agg += 1
        if depth:
            for i in range(12):
                ts = now - depth_age - 1_100 + i * 100
                prep.route_message(self._depth(i + 1, ts), ts, "depth")

    def test_F_fresh_trade_and_depth_ready(self) -> None:
        prep = EFPerpPrep(); now = now_ms(); self._warm(prep, now, True, True)
        snap = prep.snapshot("UP", now)
        self.assertTrue(snap["ready"]); self.assertGreater(snap["raw_trade_rows"], 0)
        self.assertLessEqual(snap["trade_age_ms"], EF_PERP_TRADE_STALE_MS)
        self.assertLessEqual(snap["depth_age_ms"], EF_PERP_DEPTH_STALE_MS)

    def test_G_depth_only_not_ready(self) -> None:
        prep = EFPerpPrep(); now = now_ms(); self._warm(prep, now, False, True)
        snap = prep.snapshot("UP", now)
        self.assertFalse(snap["ready"]); self.assertIsNone(snap["trade_age_ms"])

    def test_H_trade_only_not_ready(self) -> None:
        prep = EFPerpPrep(); now = now_ms(); self._warm(prep, now, True, False)
        self.assertFalse(prep.snapshot("UP", now)["ready"])
        stale = EFPerpPrep(); self._warm(stale, now, True, True, depth_age=EF_PERP_DEPTH_STALE_MS + 2_000)
        self.assertFalse(stale.snapshot("UP", now)["ready"])

    @classmethod
    def _fake_websocket(cls, trades: bool, depth: bool) -> Any:
        agg = cls._agg; dep = cls._depth
        class App:
            def __init__(self, url: str, on_message: Any = None, on_error: Any = None,
                         on_open: Any = None, on_close: Any = None) -> None:
                self.url = url; self.on_message = on_message; self.on_open = on_open; self._closed = False
            def close(self) -> None: self._closed = True
            def run_forever(self, **_kw: Any) -> None:
                if self.on_open: self.on_open(self)
                base = now_ms(); i = 0
                while not self._closed and i < 200:
                    if "/market/ws/" in self.url and trades:
                        self.on_message(self, json.dumps(agg(1000 + i, base + i, 79419.0)))
                    elif "/public/ws/" in self.url and depth and i % 3 == 0:
                        self.on_message(self, json.dumps(dep(i + 1, base + i)))
                    i += 1; time.sleep(0.002)
        return types.SimpleNamespace(WebSocketApp=App, enableTrace=lambda *a, **k: None,
                                     setdefaulttimeout=lambda *a, **k: None)

    def test_I_probe_verdicts(self) -> None:
        with mock.patch.dict(sys.modules, {"websocket": self._fake_websocket(True, True)}):
            report = run_perp_probe(0.5)
        self.assertEqual(report["verdict"], "PERP TRADE + DEPTH LIVE"); self.assertTrue(report["ready"])
        self.assertEqual(report["trade_lane"]["url"], EF_PERP_TRADE_WS_URL)
        self.assertEqual(report["depth_lane"]["url"], EF_PERP_DEPTH_WS_URL)
        self.assertGreater(report["trade_lane"]["trade_accepts"], 0); self.assertGreater(report["depth_lane"]["depth_accepts"], 0)
        self.assertIsNotNone(report["trade_lane"]["trade_age_ms"]); self.assertIn("aggTrade", report["trade_lane"]["first_trade_sample"])
        self.assertGreater(report["raw_trade_rows"], 0); self.assertGreater(report["flow_bucket_rows_30s"], 0)
        with mock.patch.dict(sys.modules, {"websocket": self._fake_websocket(False, True)}):
            self.assertEqual(run_perp_probe(0.3)["verdict"], "DEPTH LIVE, TRADE DEAD")
        with mock.patch.dict(sys.modules, {"websocket": self._fake_websocket(True, False)}):
            self.assertEqual(run_perp_probe(0.3)["verdict"], "TRADE LIVE, DEPTH DEAD")
        with mock.patch.dict(sys.modules, {"websocket": self._fake_websocket(False, False)}):
            self.assertEqual(run_perp_probe(0.3)["verdict"], "BOTH PERP LANES DEAD")
        self.assertEqual(perp_probe_verdict(1, 1), "PERP TRADE + DEPTH LIVE")
        self.assertEqual(perp_probe_verdict(0, 0), "BOTH PERP LANES DEAD")

    def test_J_no_root_aggtrade_endpoint_in_runtime(self) -> None:
        source = Path(__file__).read_text(encoding="utf-8")
        runtime = source.split("class V81AdaptationTests")[0]
        self.assertNotIn("fstream.binance.com/ws/btcusdt@aggTrade", runtime)
        self.assertNotIn("fstream.binance.com/stream?streams=", runtime)
